// ---- TABLES ----
function renderTable(tableId, data, cols) {
  const tbody = document.getElementById(tableId);
  data.forEach(row => {
    const tr = document.createElement('tr');
    tr.innerHTML = cols.map(col => `<td>${col(row)}</td>`).join('');
    tbody.appendChild(tr);
  });
}

const maxRate = top10[0].rate;
renderTable('top10Table', top10, [
  r => r.country,
  r => r.year,
  r => {
    const w = Math.round((r.rate / maxRate) * 80);
    return `<span class="rate-bar" style="width:${w}px"></span>${r.rate.toFixed(1)} <span class="badge high">High</span>`;
  }
]);

renderTable('bottom10Table', bottom10, [
  r => r.country,
  r => r.year,
  r => {
    const w = Math.round((r.rate / 1) * 40) + 4;
    return `<span class="rate-bar low" style="width:${Math.min(w,40)}px"></span>${r.rate.toFixed(3)} <span class="badge low">Low</span>`;
  }
]);

renderTable('improveTable', improvements, [
  r => r.country,
  r => `${r.startRate.toFixed(1)} (${r.start})`,
  r => `${r.endRate.toFixed(1)} (${r.end})`,
  r => `<span class="badge improve">${r.pct.toFixed(1)}%</span>`
]);

renderTable('worsenTable', deteriorations, [
  r => r.country,
  r => `${r.startRate.toFixed(2)} (${r.start})`,
  r => `${r.endRate.toFixed(1)} (${r.end})`,
